from typing import List

class Solution:
    def setZeroes(self, matrix: List[List[int]]) -> None:
        # Keep original values so new zeroes do not cascade.
        m, n = len(matrix), len(matrix[0])
        original = [row[:] for row in matrix]
        for r in range(m):
            for c in range(n):
                if original[r][c] == 0:
                    for j in range(n):
                        matrix[r][j] = 0
                    for i in range(m):
                        matrix[i][c] = 0

